## 3️⃣ Stripe – `/api/create-checkout-session.js`

Handles **single judge (0.99)** and **all judges (3.99)**.

```js
// api/create-checkout-session.js
const Stripe = require('stripe');
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

module.exports = async (req, res) => {
  if (req.method !== 'POST') {
    return res.status(405).json({ error: 'Method not allowed' });
  }

  try {
    const { type, judgeId, userId } = req.body;

    if (!type || !userId) {
      return res.status(400).json({ error: 'Missing type or userId' });
    }

    let priceId;
    if (type === 'single') {
      priceId = process.env.STRIPE_PRICE_SINGLE_JUDGE;
      if (!judgeId) {
        return res.status(400).json({ error: 'Missing judgeId for single purchase' });
      }
    } else if (type === 'all') {
      priceId = process.env.STRIPE_PRICE_ALL_JUDGES;
    } else {
      return res.status(400).json({ error: 'Invalid type' });
    }

    const session = await stripe.checkout.sessions.create({
      mode: 'payment',
      payment_method_types: ['card'],
      line_items: [{ price: priceId, quantity: 1 }],
      metadata: {
        type,
        judgeId: judgeId || '',
        userId
      },
      success_url: process.env.STRIPE_SUCCESS_URL || 'https://www.whoiswrong.io/success.html',
      cancel_url: process.env.STRIPE_CANCEL_URL || 'https://www.whoiswrong.io/cancel.html'
    });

    return res.status(200).json({ url: session.url });
  } catch (err) {
    console.error('Error creating checkout session', err);
    return res.status(500).json({ error: 'Internal server error' });
  }
};
```

Env vars needed in **Vercel**:

* `STRIPE_SECRET_KEY`
* `STRIPE_PRICE_SINGLE_JUDGE`
* `STRIPE_PRICE_ALL_JUDGES`
* `STRIPE_SUCCESS_URL`
* `STRIPE_CANCEL_URL`

